with enriched as (select s.id, s.session_id, s.event_type, s.page, s.event_time, s.duration_sec, b.device, b.country, b.browser from web_events s inner join sessions b on s.session_id = b.id), remaining_keys as (select session_id, event_type from enriched intersect all select session_id, event_type from web_events where session_id in (14, 36)), verified as (select s.* from enriched s inner join remaining_keys k on s.session_id = k.session_id and s.event_type = k.event_type), with_windows as (select *, percent_rank() over (partition by country order by duration_sec desc nulls first) as duration_sec_percent_rank from verified), enriched_web_events as (select *, max(duration_sec) over (partition by device order by cast(event_time as bigint) range between 2592000 preceding and current row) as duration_sec_max_30d, sum(duration_sec) over (partition by country order by cast(event_time as bigint) range between 604800 preceding and current row) as duration_sec_sum_7d, min(duration_sec_percent_rank) over (partition by event_type) as event_type_min_duration_sec_percent_rank from with_windows) select p.browser as session_browser, p.country as session_country, count(*) as cnt, avg(src.duration_sec_max_30d) as avg_duration_sec_max_30d, max(src.duration_sec_percent_rank) as max_duration_sec_percent_rank from enriched_web_events src inner join sessions p on src.session_id = p.id group by grouping sets ((p.browser, p.country), (p.browser), ()) order by session_country nulls last;
